import os
root = os.getcwd()
items = os.listdir(root)
for item in sorted(items):
    fp = os.path.join(root, item)
    if os.path.isdir(fp):
        sub_items = os.listdir(fp)
        print('DIR: ' + item + '/ (' + str(len(sub_items)) + ' items)')
        for sub in sub_items[:5]:
            sub_fp = os.path.join(fp, sub)
            if os.path.isfile(sub_fp):
                size = os.path.getsize(sub_fp)
                print('  ' + sub + ' (' + str(size) + ' bytes)')
            else:
                print('  ' + sub + '/')
    else:
